.pl-summary dd{margin:4px 0 0;font-size:26px;font-weight:650;color:#f1e2b8;font-variant-numeric:tabular-nums}
.pl-toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end;margin:0 0 8px;padding:14px;border:1px solid #2e2f34;border-radius:12px;background:#151619}
